-- ADR-0240 «НӨАТ хасуулах»: a customer who takes no VAT receipt for a sale has the receivable
-- reduced by a percent of that sale. Only adds (ADR-0206): two finance tables (generated by
-- drizzle-kit), two nullable columns of finance_settings, and by hand the REVOKE that keeps a
-- waiver from being deleted and the Finance Core's number series and document type for a database
-- whose company exists (a new database gets both from the api's boot step).
CREATE TABLE "customer_counter_accounts" (
	"customer_id" bigint PRIMARY KEY NOT NULL,
	"account_id" bigint NOT NULL,
	"updated_by" bigint,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE TABLE "vat_waivers" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "vat_waivers_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"invoice_id" bigint NOT NULL,
	"customer_id" bigint NOT NULL,
	"status" text DEFAULT 'POSTED' NOT NULL,
	"waiver_date" date NOT NULL,
	"pct" numeric(5, 2) NOT NULL,
	"base_amount" numeric(14, 2) NOT NULL,
	"amount" numeric(14, 2) NOT NULL,
	"account_id" bigint NOT NULL,
	"account_code" text NOT NULL,
	"description" text NOT NULL,
	"document_id" bigint,
	"document_number" text,
	"journal_entry_id" bigint,
	"created_by" bigint,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"reversed_at" timestamp with time zone,
	"reversed_by" bigint,
	"reverse_reason" text,
	"reverse_journal_entry_id" bigint,
	CONSTRAINT "vat_waivers_status" CHECK ("vat_waivers"."status" IN ('POSTED', 'REVERSED')),
	CONSTRAINT "vat_waivers_pct" CHECK ("vat_waivers"."pct" > 0 AND "vat_waivers"."pct" <= 100),
	CONSTRAINT "vat_waivers_amounts" CHECK ("vat_waivers"."amount" > 0 AND "vat_waivers"."amount" <= "vat_waivers"."base_amount"),
	CONSTRAINT "vat_waivers_description" CHECK (length("vat_waivers"."description") BETWEEN 1 AND 120),
	CONSTRAINT "vat_waivers_reversed" CHECK (("vat_waivers"."status" = 'REVERSED') = ("vat_waivers"."reversed_at" IS NOT NULL) AND ("vat_waivers"."reversed_at" IS NULL) = ("vat_waivers"."reversed_by" IS NULL)),
	CONSTRAINT "vat_waivers_reverse_reason" CHECK ("vat_waivers"."reverse_reason" IS NULL OR ("vat_waivers"."reversed_at" IS NOT NULL AND length("vat_waivers"."reverse_reason") BETWEEN 1 AND 500))
);
--> statement-breakpoint
