-- vat_waiver:data:begin
INSERT INTO fin.number_series (company_id, code, pattern, digits)
  SELECT c.id, 'VAT_WAIVER', 'НХ-{year}{month}{day}-', 4
    FROM fin.companies c
  ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO fin.document_types (company_id, code, source_system_id, class, number_mode, number_series)
  SELECT c.id, 'BTO.VAT_WAIVER', s.id, 'AR_CREDIT', 'CORE', 'VAT_WAIVER'
    FROM fin.companies c
    JOIN fin.source_systems s ON s.tenant_id = c.tenant_id AND s.code = 'BTO'
  ON CONFLICT DO NOTHING;
--> statement-breakpoint
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM fin.companies c
              JOIN fin.source_systems s ON s.tenant_id = c.tenant_id AND s.code = 'BTO'
             WHERE NOT EXISTS (SELECT 1 FROM fin.document_types t
                                WHERE t.company_id = c.id AND t.code = 'BTO.VAT_WAIVER'
                                  AND t.class = 'AR_CREDIT' AND t.number_series = 'VAT_WAIVER')) THEN
    RAISE EXCEPTION 'vat_waiver: the document type BTO.VAT_WAIVER is missing or differs';
  END IF;
END $$;
-- vat_waiver:data:end
